{
  "file_name": "ProceduralGearShape",
  "hlsl_code": "#ifndef PI
#define PI 3.14159265359
#endif

// User request: A mechanical gear shape with adjustable tooth count, tooth depth, size, and separate colors for gear body and inner hole.

// --- Basic helpers ------------------------------------------------------

// Signed distance to a circle centered at origin, radius r
inline float sdCircle(float2 p, float r)
{
    return length(p) - r;
}

// Repeat angle into [0, sectorAngle)
inline float repeatAngle(float angle, float sectorAngle)
{
    // Wrap angle into [0, 2PI)
    float twoPi = 2.0 * PI;
    float a = fmod(angle, twoPi);
    if (a < 0.0) a += twoPi;
    // Sector repeat
    float k = floor(a / sectorAngle);
    return a - k * sectorAngle;
}

// PLAN:
// 1) Map UV (0..1) to centered coordinates around (0.5,0.5) and scale by GearSize.
// 2) Compute polar coordinates (radius, angle) from centered position.
// 3) Use angular repetition based on ToothCount to model a single tooth profile.
// 4) Build radial SDF: base gear radius plus a tooth wedge between two radial extents using max().
// 5) Subtract an inner hole circle to get a gear ring; derive masks via smoothstep for AA.
// 6) Mix GearBodyColor for ring and HoleColor for inner hole; outside is transparent via alpha.

void FunctionName_float(
    float2 UV,
    float GearSize,
    float ToothCount,
    float ToothDepth,
    float BaseThickness,
    float HoleRadius,
    float4 GearBodyColor,
    float4 HoleColor,
    out float4 outColor)
{
    // 1) Center UV and scale by GearSize (0.5 ≈ half screen)
    float2 centered = (UV - 0.5) / max(GearSize, 1e-4);

    // 2) Polar coordinates
    float r = length(centered);
    float angle = atan2(centered.y, centered.x); // range -PI..PI

    // 3) Angular repetition for teeth
    float teeth = max(ToothCount, 1.0); // avoid division by zero
    float sectorAngle = 2.0 * PI / teeth;
    // Bring angle into [0, sectorAngle)
    float a = repeatAngle(angle, sectorAngle);
    // Symmetrize around center of tooth (so tooth is centered in its sector)
    float halfSector = 0.5 * sectorAngle;
    float localAngle = a - halfSector;

    // Normalize local angle to [-1,1] within the tooth width control
    // Angular half-width of tooth body (sharper or wider teeth)
    float toothAngularHalf = halfSector * clamp(BaseThickness, 0.05, 0.95);
    float angNorm = abs(localAngle) / max(toothAngularHalf, 1e-4); // >=0

    // 4) Radial profile for gear + tooth using SDF composition
    float baseRadius = 0.5; // base gear radius in local space

    // ToothDepth controls how far teeth extend beyond baseRadius
    float toothExtent = baseRadius + ToothDepth;

    // Start with base disk: dBase < 0 inside main gear body
    float dBase = r - baseRadius;

    // Tooth radial band SDF: negative inside the radial band of the tooth
    // We'll clamp to zero outside angular tooth region via angNorm.
    // Make radial tooth profile: inner at baseRadius, outer at toothExtent
    float dToothRadialInner = r - baseRadius;
    float dToothRadialOuter = toothExtent - r;
    float dToothBand = max(dToothRadialInner, 0.0) - max(-dToothRadialOuter, 0.0);

    // Angular falloff: when angNorm>1, we want tooth to vanish (positive SDF)
    float angFalloff = angNorm - 1.0;

    // Combine radial tooth band and angular limit with max (intersection)
    float dTooth = max(dToothBand, angFalloff * baseRadius);

    // Full gear SDF: union of base disk and teeth (min)
    float dGear = min(dBase, dTooth);

    // 5) Inner hole: subtract circle
    float innerR = clamp(HoleRadius, 0.0, baseRadius - 0.02);
    float dHole = sdCircle(centered, innerR);

    // Gear ring = gear minus inner hole: max(dGear, -dHole)
    float dRing = max(dGear, -dHole);

    // Outer AA
    float aaOuter = fwidth(dRing);
    float ringMask = 1.0 - smoothstep(0.0, aaOuter, dRing); // 1 inside ring

    // Inner hole mask (purely cosmetic, to color the hole area)
    float aaHole = fwidth(dHole);
    float holeFill = 1.0 - smoothstep(0.0, aaHole, dHole); // 1 inside hole

    // 6) Compose colors
    float3 ringColor = GearBodyColor.rgb;
    float3 holeColor = HoleColor.rgb;

    // Outside gear: mask = 0 → transparent
    // Inside hole but outside ring: use hole color
    // Inside ring: use gear color
    float3 finalColor = holeColor * holeFill;
    finalColor = lerp(finalColor, ringColor, ringMask);

    float alpha = saturate(max(ringMask, holeFill));

    outColor = float4(finalColor * alpha, alpha);
}
