{
  "code": "#ifndef PI
#define PI 3.14159265359
#endif

// Mechanical gear with explicit tooth silhouette.
// Adjustable tooth count, depth, size, and separate colors for body and inner hole.

// Signed distance to a circle centered at origin, radius r
inline float sdCircle(float2 p, float r)
{
    return length(p) - r;
}

// Wrap angle to [0, 2PI)
inline float wrapAngle(float a)
{
    float twoPi = 2.0 * PI;
    a = fmod(a, twoPi);
    if (a < 0.0) a += twoPi;
    return a;
}

void FunctionName_float(
    float2 UV,
    float GearSize,
    float ToothCount,
    float ToothDepth,
    float BaseThickness,
    float HoleRadius,
    float4 GearBodyColor,
    float4 HoleColor,
    out float4 outColor)
{
    // 1) Center and scale UV
    float2 p = (UV - 0.5) / max(GearSize, 1e-4);

    // 2) Polar coordinates
    float r = length(p);
    float angle = atan2(p.y, p.x); // -PI..PI
    angle = wrapAngle(angle);      // 0..2PI

    // 3) Tooth parameters
    float teeth = max(ToothCount, 1.0);
    float sectorAngle = 2.0 * PI / teeth;      // full angular span per tooth
    float halfSector = 0.5 * sectorAngle;

    // Base gear radius in local space
    float baseRadius = 0.5;
    // Tooth depth extends beyond baseRadius
    float toothDepth = max(ToothDepth, 0.0);
    float toothOuterRadius = baseRadius + toothDepth;

    // BaseThickness controls how wide each tooth is within its angular sector
    float toothAngularHalf = halfSector * clamp(BaseThickness, 0.1, 0.95);

    // 4) Normalize angle into local tooth space
    float sectorIndex = floor(angle / sectorAngle);
    float localAngle = angle - (sectorIndex + 0.5) * sectorAngle; // center tooth at 0

    // Compute how far we are from the tooth body in angle
    float angAbs = abs(localAngle);

    // Angular distance outside the tooth body (positive outside)
    float angOutside = angAbs - toothAngularHalf;

    // Convert angular distance to approximate radial offset at baseRadius
    float angRadiusOffset = angOutside * baseRadius;

    // 5) Build radial SDF for tooth silhouette
    // We want a tooth shaped like a rectangular step in polar space:
    // - Inside tooth area: radius between baseRadius and toothOuterRadius.
    // Use a simple SDF: intersection of outer circle and outside of inner circle

    // Outer of tooth (cap) circle: inside when r < toothOuterRadius
    float dOuter = r - toothOuterRadius;            // <0 inside outer cap

    // Inner of tooth: outside of inner circle r > baseRadius
    float dInner = baseRadius - r;                  // <0 inside inner base; we want OUTSIDE, so we use -dInner

    // Intersection in radius: ring from baseRadius to toothOuterRadius
    float dRadialRing = max(dOuter, dInner);        // <0 only between baseRadius and toothOuterRadius

    // Add angular limitation: shrink tooth ring to central angular zone
    // Outside tooth angular zone, distance grows positive via angRadiusOffset.
    float dTooth = max(dRadialRing, angRadiusOffset);

    // 6) Base disk for gear body (without teeth)
    float dBase = r - baseRadius;

    // 7) Union of base disk and teeth
    float dGear = min(dBase, dTooth);

    // 8) Inner hole subtraction
    float innerR = clamp(HoleRadius, 0.0, baseRadius - 0.02);
    float dHole = sdCircle(p, innerR);

    // Gear ring: gear minus interior of hole
    float dRing = max(dGear, -dHole);

    // 9) Anti-alias masks
    float aaRing = fwidth(dRing);
    float ringMask = 1.0 - smoothstep(0.0, aaRing, dRing); // 1 inside ring

    float aaHole = fwidth(dHole);
    float holeMask = 1.0 - smoothstep(0.0, aaHole, dHole); // 1 inside hole

    // 10) Colors
    float3 ringColor = GearBodyColor.rgb;
    float3 holeColor = HoleColor.rgb;

    // Start with hole color inside hole, else background (black/transparent)
    float3 color = holeColor * holeMask;

    // Overwrite with gear body where ring exists
    color = lerp(color, ringColor, ringMask);

    float alpha = saturate(max(ringMask, holeMask));

    outColor = float4(color * alpha, alpha);
}
