  "hlsl": "float4 GearSize;      // x: outer radius\nfloat4 ToothCount;    // x: number of teeth\nfloat4 ToothDepth;    // x: depth of tooth from outer radius inward\nfloat4 BaseThickness; // x: ratio of base circle to outer radius\nfloat4 HoleRadius;    // x: inner hole radius\nfloat4 GearBodyColor; // rgba\nfloat4 HoleColor;     // rgba\n\nfloat2 rotate2D(float2 p, float a)\n{\n    float s = sin(a);\n    float c = cos(a);\n    return float2(c * p.x - s * p.y, s * p.x + c * p.y);\n}\n\nfloat gearSignedDistance(float2 p)\n{\n    float r = length(p);\n    float angle = atan2(p.y, p.x);\n\n    float teeth = max(1.0, ToothCount.x);\n    float sectorAngle = 2.0 * 3.14159265 / teeth;\n\n    float halfSector = sectorAngle * 0.5;\n    float localAngle = abs(fmod(angle + halfSector, sectorAngle) - halfSector);\n\n    float outerR = GearSize.x;\n    float baseR = outerR * saturate(BaseThickness.x);\n    float toothDepth = ToothDepth.x;\n\n    float toothOuterR = outerR;\n    float toothInnerR = max(0.0, outerR - toothDepth);\n\n    float toothAngularWidth = sectorAngle * 0.4;\n\n    float radialLimit = lerp(toothInnerR, toothOuterR, smoothstep(toothAngularWidth, 0.0, localAngle));\n\n    float dOuter = r - radialLimit;\n    float dBase = r - baseR;\n\n    float dGear = min(dOuter, dBase);\n\n    return dGear;\n}\n\nfloat4 mainImage(float2 uv) : SV_Target\n{\n    float2 p = uv * 2.0 - 1.0;\n\n    float scale = 1.0 / max(GearSize.x, 0.001);\n    p *= scale * 0.8;\n\n    float dGear = gearSignedDistance(p);\n    float r = length(p);\n\n    float holeR = HoleRadius.x * scale;\n\n    bool inHole = (r < holeR);\n    bool inGear = (dGear < 0.0) && !inHole;\n\n    float4 col = float4(0, 0, 0, 0);\n\n    if (inHole)\n    {\n        col = HoleColor;\n    }\n    else if (inGear)\n    {\n        float edge = smoothstep(0.0, -0.01, dGear);\n        col = lerp(float4(0, 0, 0, 1), GearBodyColor, edge);\n    }\n\n    return col;\n}"
