  "hlsl": "cbuffer ShaderProperties : register(b0)
{
    float4 GearSize;       // x = gear radius
    float4 ToothCount;     // x = number of teeth
    float4 ToothDepth;     // x = tooth depth (radial)
    float4 BaseThickness;  // x = base circle fraction of GearSize
    float4 HoleRadius;     // x = inner hole radius
    float4 GearBodyColor;  // rgba
    float4 HoleColor;      // rgba
};

static const float PI = 3.14159265359;

float sdfCircle(float2 p, float r)
{
    return length(p) - r;
}

float gearSDF(float2 p)
{
    float r = length(p);
    float ang = atan2(p.y, p.x);

    // Normalize angle to [0, 2PI)
    ang = (ang < 0.0) ? ang + 2.0 * PI : ang;

    float teeth = max(ToothCount.x, 1.0);
    float toothAngle = 2.0 * PI / teeth;

    // Position within one tooth sector [-0.5, 0.5]
    float a = (ang / toothAngle) - floor(ang / toothAngle) - 0.5;

    // Base radius and outer radius of tooth
    float baseR = GearSize.x * BaseThickness.x;
    float outerR = GearSize.x;
    float toothDepth = ToothDepth.x * GearSize.x;
    float toothInnerR = outerR - toothDepth;

    // Angular width of the tooth (keep some gap between teeth)
    float toothAngularWidth = 0.35; // 35% of each sector is tooth

    float absA = abs(a) / (0.5 * toothAngularWidth);
    float toothMask = saturate(1.0 - absA);

    // Interpolate radius between base and outer depending on toothMask
    float targetR = lerp(baseR, outerR, toothMask);

    // Clamp minimum radius for tooth base to toothInnerR
    targetR = max(targetR, toothInnerR);

    // Signed distance: positive outside, negative inside
    return r - targetR;
}

float4 RenderPixel(float2 uv) : SV_Target
{
    // Map UV (0..1) to centered coordinates (-1..1)
    float2 p = (uv * 2.0 - 1.0);

    // Uniform scaling, keep aspect ratio assuming square render target
    float2 pp = p;

    // Gear signed distance
    float dGear = gearSDF(pp);

    // Inner hole signed distance
    float dHole = sdfCircle(pp, HoleRadius.x);

    // Base colors
    float4 col = float4(0.0, 0.0, 0.0, 0.0);

    // Inside gear body (including hole area for now)
    if (dGear < 0.0)
    {
        col = GearBodyColor;
    }

    // Carve inner hole: where hole is inside, override with HoleColor
    if (dHole < 0.0)
    {
        col = HoleColor;
    }

    // Optional antialiasing on edges using distance fields
    float aa = fwidth(dGear);
    float edge = smoothstep(0.0, aa, dGear);
    col.rgb = lerp(col.rgb, float3(0.0, 0.0, 0.0), edge * 0.0);

    // Alpha based on being within gear or hole to keep opaque inside shapes
    float inside = (dGear < 0.0 || dHole < 0.0) ? 1.0 : 0.0;
    col.a = inside;

    return col;
}
"
