{
  "file_name": "SoftCartoonCloud",
  "hlsl_code": "#ifndef PI
#define PI 3.14159265359
#endif

// Signed distance to a circle centered at origin with radius r
inline float sdCircle(float2 p, float r)
{
    return length(p) - r;
}

// Smooth union of two SDFs for soft blending
inline float opSmoothUnion(float d1, float d2, float k)
{
    // k > 0 for smoothness
    float h = saturate(0.5 + 0.5 * (d2 - d1) / k);
    return lerp(d2, d1, h) - k * h * (1.0 - h);
}

// MAIN: Soft cartoon-style multi-bump cloud
void FunctionName_float(
    float2 UV,
    float Size,
    float2 BumpOffset1,
    float2 BumpOffset2,
    float2 BumpOffset3,
    float2 BumpOffset4,
    float4 Color,
    out float4 outColor)
{
    // User request: A soft cartoon-style cloud made from multiple rounded bumps, organic, adjustable size, single fill color with smooth edges.

    // PLAN:
    // 1) Remap UV to centered coordinates around (0.5,0.5) and scale by Size.
    // 2) Define several circle SDFs (bumps) with slightly different positions and radii.
    // 3) Combine them with smooth unions to get a soft, organic cloud silhouette.
    // 4) Use a fixed smoothstep band for anti-aliasing around the final SDF.
    // 5) Output single fill color multiplied by the mask, with alpha = mask.

    // 1) Center UV and scale by Size (0.5 ≈ half screen, 1.0 ≈ full screen)
    float2 centered = UV - float2(0.5, 0.5);
    float safeSize = max(Size, 0.001);
    centered /= safeSize;

    // 2) Define circle bumps.
    // Base layout: one central large bump, two upper side bumps, one lower bump.
    // User offsets (BumpOffset1..4) allow per-cloud asymmetry.

    // Central main bump
    float2 p0 = centered - (float2(0.00, 0.00) + BumpOffset1);
    float r0 = 0.7;
    float d0 = sdCircle(p0, r0);

    // Left upper bump
    float2 p1 = centered - (float2(-0.6, 0.15) + BumpOffset2);
    float r1 = 0.55;
    float d1 = sdCircle(p1, r1);

    // Right upper bump
    float2 p2 = centered - (float2(0.65, 0.20) + BumpOffset3);
    float r2 = 0.5;
    float d2 = sdCircle(p2, r2);

    // Lower wider bump (to flatten bottom slightly)
    float2 p3 = centered - (float2(0.05, -0.55) + BumpOffset4);
    float r3 = 0.9;
    float d3 = sdCircle(p3, r3);

    // 3) Combine with smooth unions for soft transitions between bumps
    float k = 0.4; // smoothness factor
    float d = d0;
    d = opSmoothUnion(d, d1, k);
    d = opSmoothUnion(d, d2, k);
    d = opSmoothUnion(d, d3, k);

    // 4) Anti-aliased edge: negative inside, positive outside
    float edge = smoothstep(0.01, -0.01, d);

    // 5) Final color with alpha = coverage
    float mask = edge;
    float3 rgb = Color.rgb * mask;
    outColor = float4(rgb, mask);
}
