  "hlsl_code": "#ifndef PI
#define PI 3.14159265359
#endif

// Signed distance to a circle centered at origin with given radius
float sdCircle(float2 p, float radius)
{
    return length(p) - radius;
}

// Boolean subtraction: shape A minus shape B
float opSubtract(float distA, float distB)
{
    return max(-distB, distA);
}

void FunctionName_float(float2 UV, float Size, float Thickness, float InnerOffset, float4 Color, out float4 outColor)
{
    // User request: A crescent moon shape created by cutting one circle out of another. The thickness of the crescent should be adjustable. The moon should stay centered and clearly visible. Single solid fill color.

    // PLAN:
    // 1) Map UV to local coordinates centered at (0.5, 0.5) and scale by Size.
    // 2) Compute SDF for the outer circle (main disk) with radius = Size.
    // 3) Compute SDF for the inner circle shifted horizontally by InnerOffset * Size.
    // 4) Use opSubtract to cut the inner circle from the outer, forming a crescent.
    // 5) Use Thickness to push an additional inner band, thinning or thickening the crescent.
    // 6) Apply smoothstep-based anti-aliasing and output Color with alpha mask.

    // 1) Center UV and scale by Size (0.5 = half screen in each direction)
    float2 centered = UV - 0.5;
    float safeSize = max(Size, 1e-4);
    float2 p = centered / safeSize;

    // 2) Outer circle SDF (unit radius in scaled space)
    float outerRadius = 1.0;
    float dOuter = sdCircle(p, outerRadius);

    // 3) Inner circle SDF (shifted to the right to create crescent cut)
    // InnerOffset is in units of Size, normalized by Size scaling above.
    float offsetNorm = InnerOffset / safeSize;
    float2 innerCenter = float2(offsetNorm, 0.0);
    float innerRadius = outerRadius;
    float dInner = sdCircle(p - innerCenter, innerRadius);

    // 4) Base crescent via CSG subtraction: outer minus inner
    float dCrescent = opSubtract(dOuter, dInner);

    // 5) Apply Thickness control as an inner offset of the crescent shell
    // Thickness is given in UV units; convert to our normalized space
    float thicknessNorm = Thickness / safeSize;
    thicknessNorm = max(thicknessNorm, 0.0);
    float dCrescentThinned = dCrescent + thicknessNorm;

    // Choose between full crescent and banded version by blending
    // When Thickness is 0, we use the full crescent; as Thickness grows, we thin it.
    float t = saturate(thicknessNorm * 0.5); // simple remap so small values keep full body
    float d = lerp(dCrescent, dCrescentThinned, t);

    // 6) Anti-aliased edge and final color
    float aa = fwidth(d);
    aa = max(aa, 1e-4);
    float mask = 1.0 - smoothstep(0.0, aa, d);

    outColor = float4(Color.rgb * mask, mask);
}
