  "file_name": "StylizedFlower",
  "hlsl_code": "#ifndef PI
#define PI 3.14159265359
#endif

// Simple circle SDF: negative inside, positive outside
float sdCircle(float2 p, float radius)
{
    return length(p) - radius;
}

// PLAN:
// 1) Map UV to local coordinates centered at (0.5, 0.5) and scale by PetalLength.
// 2) Convert to polar: radius r and angle a.
// 3) Repeat angle into petal wedge using PetalCount.
// 4) Build petal SDF as intersection of radial band and angular wedge.
// 5) Build center circle SDF.
// 6) Combine SDFs (min of petal and center) and use smoothstep for AA.
// 7) Use separate colors for petals and center based on which SDF is closer.
// 8) Output final color with alpha equal to coverage.

void FunctionName_float(
    float2 UV,
    float PetalCount,
    float PetalLength,
    float PetalWidth,
    float CenterRadius,
    float4 PetalColor,
    float4 CenterColor,
    out float4 outColor)
{
    // Comment of exact user request:
    // A stylized flower with repeated petals arranged in a circular pattern. The number of petals should be adjustable. Petal length and width should be adjustable. I want separate colors for the petals and the center.

    // Center UV coordinates around (0.5, 0.5)
    float2 p = UV - float2(0.5, 0.5);

    // Avoid degenerate parameters
    float petals = max(PetalCount, 1.0);
    float petalLen = max(PetalLength, 0.001);
    float petalWidth = max(PetalWidth, 0.001);
    float centerR = max(CenterRadius, 0.0);

    // Scale so that PetalLength roughly controls radius extent in UV space
    p /= petalLen;

    // Polar coordinates
    float r = length(p);
    float angle = atan2(p.y, p.x); // range [-PI, PI]

    // Angular repetition: fold angle into a single petal wedge
    float sectorAngle = (2.0 * PI) / petals;
    float halfSector = 0.5 * sectorAngle;
    // Wrap angle into [-halfSector, halfSector]
    float k = floor((angle + halfSector) / sectorAngle);
    float localAngle = angle - k * sectorAngle;

    // Petal SDF
    // Radial: thin ring band around r = 1
    float radialDist = abs(r - 1.0);
    // Angular: distance from center angle
    float angularDist = abs(localAngle);
    // Normalize angular distance into radial units using PetalWidth as control
    float angularLimit = max(petalWidth, 0.001);
    float angularNorm = angularDist / angularLimit;

    // Combine radial and angular distances via intersection (max)
    float petalSDF = max(radialDist, angularNorm - 1.0);

    // Center circle SDF (use original unscaled p so CenterRadius is in UV units)
    float2 pc = UV - float2(0.5, 0.5);
    float centerSDF = sdCircle(pc, centerR);

    // Combined flower mask: min of petals and center
    float flowerSDF = min(petalSDF, centerSDF);

    // Anti-alias amount
    float aa = fwidth(flowerSDF);
    aa = max(aa, 0.001);

    // Coverage mask for overall flower
    float flowerMask = 1.0 - smoothstep(0.0, aa, flowerSDF);

    // Separate masks for center and petals
    float centerMask = 1.0 - smoothstep(0.0, aa, centerSDF);
    float petalMask = 1.0 - smoothstep(0.0, aa, petalSDF);

    // Ensure masks are within [0,1]
    centerMask = saturate(centerMask);
    petalMask = saturate(petalMask);

    // Prefer center color where center exists, otherwise petals
    float3 color = float3(0.0, 0.0, 0.0);
    float alpha = 0.0;

    // Blend center and petal colors based on their masks
    float totalMask = max(centerMask, petalMask);
    if (totalMask > 0.0)
    {
        float centerWeight = centerMask / max(totalMask, 1e-4);
        float petalWeight = petalMask / max(totalMask, 1e-4);
        color = CenterColor.rgb * centerWeight + PetalColor.rgb * petalWeight;
        alpha = totalMask;
    }

    // Multiply by overall flower coverage to respect outer AA boundary
    color *= flowerMask;
    alpha *= flowerMask;

    outColor = float4(color, alpha);
}
