// Simple circle SDF: negative inside, positive outside
float sdCircle(float2 p, float radius)
{
    return length(p) - radius;
}

// Capsule SDF used to build a solid, filled petal shape
float sdCapsule(float2 p, float2 a, float2 b, float r)
{
    float2 pa = p - a;
    float2 ba = b - a;
    float h = saturate(dot(pa, ba) / dot(ba, ba));
    return length(pa - ba * h) - r;
}

void FunctionName_float(
    float2 UV,
    float PetalCount,
    float PetalLength,
    float PetalWidth,
    float CenterRadius,
    float4 PetalColor,
    float4 CenterColor,
    out float4 outColor)
{
    // Center UV coordinates around (0.5, 0.5)
    float2 p = UV - float2(0.5, 0.5);

    // Clamp parameters to reasonable ranges
    float petals = max(PetalCount, 1.0);
    float petalLen = max(PetalLength, 0.01);
    float petalWidth = max(PetalWidth, 0.005);
    float centerR = max(CenterRadius, 0.0);

    // Radius from center
    float r = length(p);

    // Base direction (x-axis)
    float2 baseDir = float2(1.0, 0.0);

    // Petal length in UV units: extend from edge of center outwards
    float innerR = centerR;
    float outerR = centerR + petalLen;

    // Build a single petal in local coordinates (aligned with x-axis)
    // Capsule from (innerR, 0) to (outerR, 0) with radius = petalWidth
    float2 a = baseDir * innerR;
    float2 b = baseDir * outerR;

    // Angular repetition: find closest petal direction by rotating p
    float sectorAngle = (2.0 * PI) / petals;
    float angle = atan2(p.y, p.x); // [-PI, PI]
    float k = round(angle / sectorAngle);
    float refAngle = angle - k * sectorAngle;

    // Rotate point into reference petal sector (so capsule is valid)
    float cs = cos(-k * sectorAngle);
    float sn = sin(-k * sectorAngle);
    float2 pr = float2(p.x * cs - p.y * sn, p.x * sn + p.y * cs);

    // Petal SDF: solid capsule
    float petalSDF = sdCapsule(pr, a, b, petalWidth);

    // Center circle SDF (in UV units)
    float2 pc = UV - float2(0.5, 0.5);
    float centerSDF = sdCircle(pc, centerR);

    // Anti-alias width
    float aaPetal = fwidth(petalSDF);
    float aaCenter = fwidth(centerSDF);
    aaPetal = max(aaPetal, 0.001);
    aaCenter = max(aaCenter, 0.001);

    // Separate masks for center and petals
    float petalMask = 1.0 - smoothstep(0.0, aaPetal, petalSDF);
    float centerMask = 1.0 - smoothstep(0.0, aaCenter, centerSDF);

    petalMask = saturate(petalMask);
    centerMask = saturate(centerMask);

    // Prefer center color where center exists, otherwise petals
    float totalMask = max(petalMask, centerMask);
    float3 color = float3(0.0, 0.0, 0.0);
    float alpha = 0.0;

    if (totalMask > 0.0)
    {
        float centerWeight = centerMask / max(totalMask, 1e-4);
        float petalWeight = petalMask / max(totalMask, 1e-4);
        color = CenterColor.rgb * centerWeight + PetalColor.rgb * petalWeight;
        alpha = totalMask;
    }

    outColor = float4(color, alpha);
}
