  "hlsl": "//============================================================
// Stylized Flower Shader
// - Adjustable petal count, length, width
// - Separate colors for petals and center
//============================================================

cbuffer ShaderProperties : register(b0)
{
    float4 PetalCount;   // x = number of petals
    float4 PetalLength;  // x = petal length (radius)
    float4 PetalWidth;   // x = petal angular width control
    float4 CenterRadius; // x = radius of center circle
    float4 PetalColor;   // rgba
    float4 CenterColor;  // rgba
};

struct VSInput
{
    float3 position : POSITION;
    float2 uv       : TEXCOORD0;
};

struct PSInput
{
    float4 position : SV_POSITION;
    float2 uv       : TEXCOORD0;
};

PSInput VSMain(VSInput input)
{
    PSInput output;
    // Full‑screen procedural style: pass through position, use uv as provided
    output.position = float4(input.position, 1.0);
    output.uv = input.uv;
    return output;
}

float sdCircle(float2 p, float r)
{
    return length(p) - r;
}

float flowerPetalMask(float2 p, float petalCount, float petalLength, float petalWidth)
{
    // Polar coordinates
    float r = length(p);
    float a = atan2(p.y, p.x); // -PI..PI

    // Normalize angle to 0..2PI
    const float PI = 3.14159265f;
    float twoPI = 2.0f * PI;
    a = fmod(a + twoPI, twoPI);

    // Angle step per petal
    float step = twoPI / max(petalCount, 1.0f);

    // Distance to nearest petal angle center
    float halfStep = step * 0.5f;
    float sector = floor((a + halfStep) / step);
    float centerAngle = sector * step;
    float da = abs(a - centerAngle);

    // Angular falloff (controls width)
    float angleMask = smoothstep(petalWidth, 0.0f, da);

    // Radial mask (controls length)
    float radialMask = smoothstep(0.0f, petalLength, r) * (1.0f - smoothstep(petalLength * 0.8f, petalLength, r));

    // Combine masks
    return angleMask * radialMask;
}

float4 PSMain(PSInput input) : SV_Target
{
    // Map uv from 0..1 to -1..1, centered
    float2 uv = input.uv * 2.0f - 1.0f;

    // Maintain aspect ratio assuming wider than tall if needed
    // This keeps flower roughly circular on non‑square surfaces
    // You can remove this if the engine already corrects for aspect.
    float aspect = 1.0f;
    if (aspect > 1.0f)
        uv.x *= aspect;
    else
        uv.y /= aspect;

    float petalCount  = max(PetalCount.x, 1.0f);
    float petalLength = PetalLength.x;
    float petalWidth  = max(PetalWidth.x, 0.0001f);
    float centerR     = CenterRadius.x;

    // Petal mask
    float petalMask = flowerPetalMask(uv, petalCount, petalLength, petalWidth);

    // Center mask (soft circle)
    float dCenter = sdCircle(uv, centerR);
    float centerMask = 1.0f - smoothstep(0.0f, centerR * 0.2f, dCenter);

    // Combine: center overrides petals where it overlaps
    float4 col = float4(0, 0, 0, 0);

    // Petals
    col = lerp(col, PetalColor, saturate(petalMask));

    // Center on top
    col = lerp(col, CenterColor, saturate(centerMask));

    // Optional: simple alpha from combined mask
    float alpha = saturate(max(petalMask, centerMask));
    col.a = alpha;

    return col;
}
