// 2D rotation helper
float2 rotate2D(float2 p, float angle)
{
    float ca = cos(angle);
    float sa = sin(angle);
    return float2(ca * p.x - sa * p.y, sa * p.x + ca * p.y);
}

// Regular N-point star (convex/concave) shape
// Returns 0 at edge, <0 inside, >0 outside
float sdStarRegular(float2 p, int n, float rOuter, float rInner)
{
    // Convert to polar
    float ang = atan2(p.y, p.x);
    float rad = length(p);

    // Sector angle
    float k = 2.0 * PI / (float)n;

    // Fold angle into one sector
    float halfK = 0.5 * k;
    float a = fmod(ang + halfK, k) - halfK;

    // Interpolate radius between outer and inner tips within a sector
    float t = abs(a) / halfK;              // 0 at spike axis, 1 at valley
    float r = lerp(rOuter, rInner, t);     // desired radius at this angle

    return rad - r;
}

// User request: fixed 8-point star, adjustable spike length and rotation, single fill color
