    float baseRadius  = 0.15;              // inner/core radius

    // Clamp spike length factor; 0 = no spikes, 1 = long spikes
    float s = saturate(SpikeLength);

    // Outer radius grows with spike length
    float rInner = baseRadius;
    float rOuter = baseRadius + 0.4 + 0.6 * s;  // tunable spike reach

    // Signed distance to an 8-point regular star
    float dStar = sdStarRegular(p, points, rOuter, rInner);

    // Anti-alias edge using a small transition band
    float aa = fwidth(dStar) * 1.5;
    float edge = smoothstep(aa, -aa, dStar);

    // Single fill color with star-shaped alpha mask
    outColor = float4(Color.rgb * edge, edge * Color.a);
}
