// PLAN:
// 1) Center UV around (0.5,0.5) and scale by Size to control overall spiral size.
// 2) Convert to polar coords (r, angle). Target arm radius = (angle / (2PI)) * (1/Turns).
// 3) Build an SDF for the spiral "center line" as distance to the radial arm.
// 4) Convert that center-line distance into a band SDF using LineThickness.
// 5) Use smoothstep for anti-aliasing and output a single solid color mask.

// User request: A spiral shape growing outward from the center with adjustable turns and thickness, single solid color.

void FunctionName_float(float2 UV, float Size, float Turns, float LineThickness, float4 Color, out float4 outColor)
{
    // Ensure we always initialize outColor
    outColor = float4(0.0, 0.0, 0.0, 0.0);

    // 1) Center UV and scale by size
    float2 centered = UV - float2(0.5, 0.5);
    centered /= max(Size, 1e-4);

    // Polar coordinates
    float r = length(centered);
    float angle = atan2(centered.y, centered.x); // range (-PI, PI]
    if (angle < 0.0)
    {
        angle += 2.0 * PI; // map to [0, 2PI)
    }

    // 2) Compute target spiral radius for this angle.
    // One full turn = angle from 0 to 2PI. For N turns, radius grows from 0 to 1 over angle [0, N*2PI].
    float totalAngle = Turns * 2.0 * PI;
    float t = angle / max(totalAngle, 1e-4); // normalized progression along spiral

    // Clamp t to [0,1] so spiral stops at radius 1
    t = clamp(t, 0.0, 1.0);

    float targetRadius = t; // simple Archimedean spiral: r ~ t

    // 3) Distance from current point radius to spiral center line
    float radialDist = r - targetRadius; // signed; 0 at spiral center line

    // 4) Convert radialDist to band SDF with adjustable thickness
    float halfThickness = 0.5 * LineThickness;
    float sdf = abs(radialDist) - halfThickness;

    // Optional: fade out beyond spiral end (when angle > totalAngle)
    // Compute how far past the spiral end we are and add to sdf
    float overAngle = max(angle - totalAngle, 0.0);
    sdf = max(sdf, overAngle); // ensure outside after spiral end

    // 5) Anti-aliased edge
    float aa = fwidth(sdf);
    float edge = 1.0 - smoothstep(0.0, aa, sdf);

    // Final color with alpha = mask
    float mask = edge;
    outColor = float4(Color.rgb * mask, mask);
}
