// SDF for axis-aligned box centered at origin with half extents b
float sdBox(float2 p, float2 b)
{
    float2 d = abs(p) - b;
    return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
}

// Union of two SDFs
float opUnion(float d1, float d2)
{
    return min(d1, d2);
}

// --- Main snowflake function ---
// User request: A symmetric snowflake shape with repeating branches. Adjustable branch count and thickness, balanced and centered, single fill color.
void FunctionName_float(float2 UV, float Size, float BranchCount, float BranchThickness, float4 Color, out float4 outColor)
{
    // PLAN:
    // 1) Map UV to centered coordinates around (0.5, 0.5) and scale by Size.
    // 2) Build a single vertical branch as a long thin box.
    // 3) Use angular repetition by rotating the sample point for each branch and taking union of SDFs.
    // 4) Add a small central core (box) to keep the shape balanced.
    // 5) Use smoothstep on the final SDF for anti-aliased edges and output single fill color with alpha mask.

    // 1) Center UV coordinates and scale by Size (0.5 = half screen)
    float2 p = UV - 0.5;
    float safeSize = max(Size, 0.001);
    p /= safeSize;

    // 2) Base vertical branch SDF (axis-aligned box)
    //    Half-length is relatively large so branches extend outward.
    float halfLength = 0.9;          // branch half-length in local units
    float halfWidth  = max(BranchThickness, 0.01); // thickness control
    float2 branchHalfSize = float2(halfWidth, halfLength);

    // Central core size to keep snowflake balanced
    float coreRadius = 0.25;

    // 3) Angular repetition: rotate sampling point for each branch
    float branches = max(BranchCount, 1.0);
    float angleStep = 2.0 * PI / branches;

    float dist = 1e6;

    // Limit iterations to a reasonable max for shader safety
    int maxBranches = 24;
    int intBranches = (int)clamp(branches, 1.0, (float)maxBranches);

    for (int i = 0; i < maxBranches; i++)
    {
        if (i >= intBranches) break;

        float angle = angleStep * (float)i;
        float2 pr = rotate2D(p, -angle); // rotate sample so branch stays vertical

        // Branch SDF: long thin box
        float dBranch = sdBox(pr, branchHalfSize);

        dist = opUnion(dist, dBranch);
    }

    // 4) Add central core box for balance
    float2 coreHalfSize = float2(coreRadius, coreRadius);
    float dCore = sdBox(p, coreHalfSize);
    dist = opUnion(dist, dCore);

    // 5) Anti-aliased edge and output color
    float edge = smoothstep(0.01, -0.01, dist);
    float mask = edge;
    outColor = float4(Color.rgb * mask, mask);
}
