// Signed distance to a circle (centered at origin).
float sdCircle(float2 p, float radius)
{
    return length(p) - radius;
}

// Signed distance to an axis-aligned box (centered at origin).
float sdBox(float2 p, float2 halfSize)
{
    float2 d = abs(p) - halfSize;
    float2 dMax = float2(max(d.x, 0.0), max(d.y, 0.0));
    float outside = length(dMax);
    float inside = min(max(d.x, d.y), 0.0);
    return outside + inside;
}

// Smooth union between two SDFs.
float opSmoothUnion(float d1, float d2, float k)
{
    float h = clamp(0.5 + 0.5 * (d2 - d1) / k, 0.0, 1.0);
    return lerp(d2, d1, h) - k * h * (1.0 - h);
}

void FunctionName_float(float2 UV, float Size, float4 Color, out float4 outColor)
{
    // USER REQUEST: A classic heart shape centered on the screen. The size should be adjustable while keeping the proportions. Edges should be smooth and rounded. Single fill color.

    // PLAN:
    // 1) Remap UV to centered coords and scale by Size.
    // 2) Build two circle SDFs for the top lobes of the heart.
    // 3) Build a bottom wedge/triangle via a box SDF and transforms.
    // 4) Combine with smooth unions to form the heart.
    // 5) Use smoothstep for anti-aliasing and output the colored heart with alpha.

    // 1) Center UV coordinates and scale by Size (0.5 ≈ half-screen heart).
    float2 centered = UV - float2(0.5, 0.5);
    float s = max(Size, 1e-4);
    float2 p = centered / s;

    // 2) Top lobes: two circles.
    // Positions chosen to approximate a classic heart in normalized space.
    float2 leftCenter  = float2(-0.5,  0.3);
    float2 rightCenter = float2( 0.5,  0.3);
    float  lobeRadius  = 0.7;

    float dLeft  = sdCircle(p - leftCenter,  lobeRadius);
    float dRight = sdCircle(p - rightCenter, lobeRadius);
    float dTop   = min(dLeft, dRight);

    // 3) Bottom wedge using a rotated/angled box-like shape.
    // We create a vertical diamond-like wedge by skewing coordinates
    // so that the bottom narrows into a point.
    float2 q = p;
    // Push bottom point downward slightly.
    q.y -= 0.25;
    // Mirror across x for symmetry, then create a V by scaling x with y.
    q.x = abs(q.x);
    // As y goes down, allowable x shrinks, forming a V.
    float k = 0.9; // controls taper steepness
    q.x += k * q.y;
    float2 boxHalf = float2(0.9, 1.4);
    float dBottomRaw = sdBox(q, boxHalf);

    // Invert sign below to keep interior negative where needed.
    float dBottom = dBottomRaw;

    // 4) Combine top lobes and bottom wedge with smooth unions for rounded joins.
    float kSmooth = 0.4;
    float dHeart = opSmoothUnion(dTop, dBottom, kSmooth);

    // 5) Anti-aliased edge and final color.
    float edge = smoothstep(0.01, -0.01, dHeart);
    float mask = edge;

    outColor = float4(Color.rgb * mask, mask);
}
