// Signed distance to a classic heart using an analytic formula.
// Reference form (for p in [-1,1] range):
// (x^2 + y^2 - 1)^3 - x^2 * y^3 = 0
// We use a smooth approximation via implicit distance.
float sdHeart(float2 p)
{
    // Scale to fit nicely in unit box while keeping proportions
    p.x *= 1.2;
    p.y *= 1.35;

    float x = p.x;
    float y = p.y;

    // Implicit heart function
    float a = x * x + y * y - 1.0;
    float f = a * a * a - x * x * y * y * y; // < 0 inside classic heart curve

    // Approximate distance: normalize by gradient magnitude length
    float gx = 6.0 * a * x - 2.0 * x * y * y * y;
    float gy = 6.0 * a * y - 3.0 * x * x * y * y;
    float gradLen = max(length(float2(gx, gy)), 1e-4);

    return f / gradLen;
}

void FunctionName_float(float2 UV, float Size, float4 Color, out float4 outColor)
{
    // Center UV coordinates
    float2 centered = UV - float2(0.5, 0.5);

    // Size control: smaller Size => larger heart (screen space)
    float s = max(Size, 1e-4);
    float2 p = centered / s;

    // Compute signed distance to heart shape
    float d = sdHeart(p);

    // Anti-aliased edge
    // Edge thickness is kept constant in screen space using fwidth
    float w = fwidth(d) * 1.0;
    float mask = smoothstep(w, -w, d);

    outColor = float4(Color.rgb * mask, mask * Color.a);
}
