    // Keep entire arrow centered horizontally.
    float totalWidth   = shaftLen + headSize;
    float arrowCenterX = 0.0; // already centered in p-space

    // Place shaft so that its right end meets the left edge of the head base
    float shaftHalfLen = shaftLen * 0.5;
    float headBaseX    = arrowCenterX + (totalWidth * 0.5) - headSize; // base where shaft meets head
    float shaftCenterX = headBaseX - shaftHalfLen;

    float2 shaftCenter      = float2(shaftCenterX, 0.0);
    float2 shaftP           = p - shaftCenter;
    float2 shaftHalfExtents = float2(shaftHalfLen, shaftThick * 0.5);
    float dShaft            = sdBox(shaftP, shaftHalfExtents);

    // 3) Right-pointing triangular head SDF using analytic triangle SDF
    // Triangle vertices (in centered space):
    //   v0: base bottom, v1: base top, v2: tip
    float halfHeadHeight = shaftThick * 0.5 + headSize * 0.25; // taller than shaft for readability
    float2 v0 = float2(headBaseX,             -halfHeadHeight);
    float2 v1 = float2(headBaseX,              halfHeadHeight);
    float2 v2 = float2(headBaseX + headSize,   0.0);

    // Inigo Quilez analytic triangle SDF
    float2 p0 = p - v0;
    float2 p1 = p - v1;
    float2 p2 = p - v2;

    float2 e0 = v1 - v0;
    float2 e1 = v2 - v1;
    float2 e2 = v0 - v2;

    float2 v0v1 = e0;
    float2 v1v2 = e1;
    float2 v2v0 = e2;

    float2 q0 = p0 - v0v1 * clamp(dot(p0, v0v1) / dot(v0v1, v0v1), 0.0, 1.0);
    float2 q1 = p1 - v1v2 * clamp(dot(p1, v1v2) / dot(v1v2, v1v2), 0.0, 1.0);
    float2 q2 = p2 - v2v0 * clamp(dot(p2, v2v0) / dot(v2v0, v2v0), 0.0, 1.0);

    float s = sign(v0.x * v1.y - v0.y * v1.x + v1.x * v2.y - v1.y * v2.x + v2.x * v0.y - v2.y * v0.x);

    float dTri = min(min(dot(q0, q0), dot(q1, q1)), dot(q2, q2));
    float2 bary = float2(v1.x - v0.x, v2.x - v0.x);
    float2 baryY = float2(v1.y - v0.y, v2.y - v0.y);
    float det = bary.x * baryY.y - bary.y * baryY.x;

