    float aa = fwidth(dArrow) * 1.5;
    float edge = smoothstep(aa, -aa, dArrow);

    float alpha = edge;
    float3 rgb = Color.rgb; // keep solid color, let alpha shape the arrow
    outColor = float4(rgb, alpha * Color.a);
}
