// Signed distance to axis-aligned box centered at 'center' with half-size 'halfSize'
float sdBox(float2 p, float2 center, float2 halfSize)
{
    float2 d = abs(p - center) - halfSize;
    return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
}

// Signed distance to triangle defined by vertices a, b, c
float sdTriangle(float2 p, float2 a, float2 b, float2 c)
{
    float2 ba = b - a;
    float2 pa = p - a;
    float2 cb = c - b;
    float2 pb = p - b;
    float2 ac = a - c;
    float2 pc = p - c;

    float2 nor = float2(ba.y, -ba.x);

    float2 s = float2(
        sign(dot(cross(float3(ba, 0.0), float3(pa, 0.0)), float3(0.0, 0.0, 1.0))),
        sign(dot(cross(float3(cb, 0.0), float3(pb, 0.0)), float3(0.0, 0.0, 1.0)))
    );

    float2 t = float2(
        sign(dot(cross(float3(ac, 0.0), float3(pc, 0.0)), float3(0.0, 0.0, 1.0))),
        0.0
    );

    float d1 = dot(nor, pa);
    float d2 = dot(float2(cb.y, -cb.x), pb);
    float d3 = dot(float2(ac.y, -ac.x), pc);

    float dist = max(max(d1, d2), d3);
    return dist;
}

float4 MainPS(float2 uv : TEXCOORD0) : SV_Target
{
    float2 p = uv * 2.0 - 1.0;

    float shaftLen = saturate(ShaftLength);
    float shaftThick = saturate(ShaftThickness);
    float headSize = saturate(ArrowHeadSize);

    float maxTotalLen = 0.9;
    float totalLen = saturate(shaftLen + headSize) * maxTotalLen;

    float shaftPortion = (shaftLen + 1e-5) / (shaftLen + headSize + 1e-5);
    float shaftTotalLen = totalLen * shaftPortion;
    float headTotalLen = totalLen - shaftTotalLen;

    float2 shaftCenter = float2(-totalLen * 0.5 + shaftTotalLen * 0.5, 0.0);
    float2 shaftHalfSize = float2(shaftTotalLen * 0.5, max(0.02, shaftThick * 0.5));

    float headBaseX = shaftCenter.x + shaftHalfSize.x;
    float2 a = float2(headBaseX, -shaftHalfSize.y * 1.2);
    float2 b = float2(headBaseX, shaftHalfSize.y * 1.2);
    float2 c = float2(headBaseX + headTotalLen, 0.0);

    float dShaft = sdBox(p, shaftCenter, shaftHalfSize);
    float dHead = sdTriangle(p, a, b, c);

    float d = min(dShaft, dHead);

    float feather = fwidth(d) * 1.5;
    float alpha = smoothstep(0.0, -feather, d);

    float4 col = Color;
    col.a *= alpha;
    return col;
