    float2 v1 = C - B;
    float2 v2 = A - C;

    float2 ap = p - A;
    float2 bp = p - B;
    float2 cp = p - C;

    float e0 = v0.x * ap.y - v0.y * ap.x; // edge AB
    float e1 = v1.x * bp.y - v1.y * bp.x; // edge BC
    float e2 = v2.x * cp.y - v2.y * cp.x; // edge CA

    // Normalize sign so that interior is non-negative
    float s = sign((C.x - A.x) * (B.y - A.y) - (C.y - A.y) * (B.x - A.x));
    e0 *= s; e1 *= s; e2 *= s;

    float headMask = step(0.0, e0) * step(0.0, e1) * step(0.0, e2);

    // Combine masks
    float mask = saturate(shaftMask + headMask);

    // Single solid color, transparent background
    float4 col = Color;
    col.a *= mask;
    col.rgb *= mask;

    return col;
}
